def transform(grid):
    """Expand the central marker into a downward 2-chevron, then 1-stripes."""
    width = len(grid[0])
    center = next(c for c, value in enumerate(grid[0]) if value == 2)
    out = [[0] * width for _ in range(width)]
    for r in range(width):
        if r <= center and r <= width - 1 - center:
            left, right = center - r, center + r
            out[r][left] = 2
            out[r][right] = 2
        if r >= 3:
            for c in range(width):
                if center - r <= c <= center + r and (c - r) % 4 == 2 and out[r][c] == 0:
                    out[r][c] = 1
    return out

