def transform(grid):
    """Build expanding diagonals and the periodic interior stripe pattern."""
    width = len(grid[0])
    center = next(c for c, value in enumerate(grid[0]) if value == 2)
    out = [[0] * width for _ in range(width)]
    for r in range(width):
        left, right = center - r, center + r
        if 0 <= left < width:
            out[r][left] = 2
        if 0 <= right < width:
            out[r][right] = 2
        if r >= 3:
            for c in range(max(0, left), min(width - 1, right) + 1):
                if (c - r + center) % 4 == 0 and out[r][c] == 0:
                    out[r][c] = 1
    return out
